import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  Image,
  TouchableOpacity,
} from 'react-native';
import {
  Ux4gAppHeader,
  Ux4gInputField,
  Ux4gButton,
  Ux4gOutlineButton,
  Ux4gDivider,
  Ux4gThemeProvider,
  UX4GColors,
  defaultUx4gTypography,
} from 'ux4g-react-native-design-system';
import Svg, { Path, Circle } from 'react-native-svg';

const ErrorIcon = ({ size = 18, color = UX4GColors.red600 }: { size?: number; color?: string }) => (
  <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <Circle cx="12" cy="12" r="10" fill={color} />
    <Path d="M12 7v6M12 16v1" stroke="#FFFFFF" strokeWidth="2" strokeLinecap="round" />
  </Svg>
);

export const SignInAccountCardPattern = () => {
  const [mobileNumber, setMobileNumber] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Strictly enforce numbers only (0-9) and 10 digits
  const handleMobileChange = (val: string) => {
    const numericValue = val.replace(/\\D/g, '').slice(0, 10);
    setMobileNumber(numericValue);
  };

  const handleSendOtp = () => {
    setIsLoading(true);
    setTimeout(() => setIsLoading(false), 1500);
  };

  return (
    <View style={styles.screen}>
      {/* 1. Official Government Header with Bottom Elevation & Separation Line */}
      <Ux4gAppHeader
        title=""
        variant="light"
        elevation={2}
        useSafeArea={false}
        horizontalPadding={16}
        leadingSpacing={8}
        backgroundColor={UX4GColors.neutral0}
        borderColor={UX4GColors.neutral200}
        leadingWidgets={[
          <Image
            key="emblem"
            source={{ uri: '/national_emblem_logo.svg' }}
            style={styles.emblemLogo}
            resizeMode="contain"
          />,
          <View key="divider" style={styles.headerDivider} />,
          <Image
            key="union"
            source={{ uri: '/Union.svg' }}
            style={styles.unionLogo}
            resizeMode="contain"
          />,
        ]}
      />
      <Ux4gDivider color={UX4GColors.neutral200} />

      {/* 2. Soft Purple Background (UX4GColors.primary100 / #DCD4FF) & Floating Card */}
      <ScrollView contentContainerStyle={styles.scrollContainer}>
        <View style={styles.card}>
          {/* Title with defaultUx4gTypography.hM_strong */}
          <Text style={styles.title}>Sign in to your account</Text>
          {/* Subtitle with defaultUx4gTypography.bM_default */}
          <Text style={styles.subtitle}>
            Access your government services securely
          </Text>

          <View style={{ height: 20 }} />

          {/* Mobile Number Input (Numbers only) */}
          <Ux4gInputField
            label="Mobile Number"
            placeholder="Enter mobile number"
            prefixText="+91"
            value={mobileNumber}
            onValueChange={handleMobileChange}
            keyboardType="numeric"
            type="number"
            maxLength={10}
          />

          <View style={{ height: 16 }} />

          {/* Status Message Alert Banner */}
          <View style={styles.statusBanner}>
            <View style={styles.statusHeaderRow}>
              <ErrorIcon size={18} color={UX4GColors.red600} />
              <Text style={styles.statusTitle}>Your status message goes here</Text>
            </View>
            <View style={styles.statusActionRow}>
              <TouchableOpacity onPress={() => console.log('Take action')}>
                <Text style={styles.actionText}>Take action</Text>
              </TouchableOpacity>
              <View style={styles.attemptBadge}>
                <Text style={styles.attemptText}>Attempt 1 of 5</Text>
              </View>
            </View>
          </View>

          <View style={{ height: 20 }} />

          {/* Primary CTA: Send OTP */}
          <Ux4gButton
            text="Send OTP"
            variant="primary"
            size="large"
            isLoading={isLoading}
            onPress={handleSendOtp}
            style={styles.sendOtpButton}
          />

          <View style={{ height: 16 }} />

          {/* OR Divider with defaultUx4gTypography.lM_default */}
          <Ux4gDivider
            label="OR"
            color={UX4GColors.neutral200}
            labelStyle={styles.dividerLabel}
          />

          <View style={{ height: 16 }} />

          {/* Secondary CTA: Sign in with Aadhaar */}
          <Ux4gOutlineButton
            text="Sign in with Aadhaar"
            onPress={() => console.log('Sign in with Aadhaar')}
            style={styles.aadhaarButton}
          />

          <View style={{ height: 24 }} />

          {/* Register Link */}
          <TouchableOpacity
            style={styles.registerLinkContainer}
            onPress={() => console.log('Register')}
          >
            <Text style={styles.registerText}>New user? Register here</Text>
          </TouchableOpacity>
        </View>

        {/* 3. Powered by Digital India Footer with defaultUx4gTypography.lS_default */}
        <View style={styles.footer}>
          <Text style={styles.poweredByText}>Powered by -</Text>
          <Image
            source={{ uri: '/Digital_India_logo.svg' }}
            style={styles.digitalIndiaLogo}
            resizeMode="contain"
          />
        </View>
      </ScrollView>
    </View>
  );
};

